        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def max_prime(lst):
        max_p = -1
        for num in lst:
            if is_prime(num) and num > max_p:
                max_p = num
        return max_p

    def sum_of_digits(n):
        return sum(int(digit) for digit in str(n))

    max_p = max_prime(lst)
    return sum_of_digits(max_p) if max_p != -1 else 0

